urlset:

  {{ base_url }}/
  daily
  1.0

{% for cat in categories %}

  {{ base_url }}{{ cat.get_absolute_url }}
  weekly
  0.8

{% endfor %}
{% for prod in products %}

  {{ base_url }}{{ prod.get_absolute_url }}
  {{ prod.updated_at|date:"Y-m-d" }}
  daily
  0.9

{% endfor %}
{% for page in pages %}

  {{ base_url }}{{ page.get_absolute_url }}
  monthly
  0.5

{% endfor %}
